select case when year(shipped_date) < 2024 then 'before_2024' when year(shipped_date) = 2024 then '2024' else 'after_2024' end as shipped_cohort, max(cost) as max_cost, round((100 * sum(case when status = 'IN_TRANSIT' then 1 else 0 end)) / count(*), 1) as pct_in_transit from shipments where delivered_date <= '2023-04-21' group by case when year(shipped_date) < 2024 then 'before_2024' when year(shipped_date) = 2024 then '2024' else 'after_2024' end
